    47	                .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
    48	                .build();
    49	        this.server = Javalin.create(config -> {
    50	            config.showJavalinBanner = false;
    51	            config.jsonMapper(new JavalinJackson(jsonMapper, false));
    52	        });
    53	        registerRoutes();
    54	        registerErrorHandling();
    55	    }
    56	
    57	    public Javalin server() {
    58	        return server;
    59	    }
    60	
    61	    private void registerRoutes() {
    62	        server.get("/rooms", ctx -> ctx.json(rooms.all()));
    63	
    64	        server.post("/reservations", ctx -> {
    65	            NewReservation request = readNewReservation(ctx);
    66	            ctx.status(201).json(new ReservationResponse(reservations.create(request)));
    67	        });
    68	        server.get("/reservations/{id}", ctx ->
    69	                ctx.json(new ReservationResponse(reservations.find(reservationId(ctx)))));
    70	        server.post("/reservations/{id}/confirmation", ctx ->
    71	                ctx.json(new ReservationResponse(reservations.confirm(reservationId(ctx)))));
    72	        server.post("/reservations/{id}/cancellation", ctx ->
    73	                ctx.json(new ReservationResponse(reservations.cancel(reservationId(ctx)))));
    74	        server.post("/reservations/{id}/check-in", ctx ->
    75	                ctx.json(new ReservationResponse(reservations.checkIn(reservationId(ctx)))));
    76	        server.post("/reservations/{id}/check-out", ctx ->
    77	                ctx.json(reservations.checkOut(reservationId(ctx))));
    78	        server.get("/reservations/{id}/document", ctx ->
    79	                ctx.json(reservations.receiptCopy(reservationId(ctx))));
    80	
    81	        server.get("/messages", ctx -> ctx.json(sentMessages.all()));
    82	
    83	        server.get("/reports/occupancy", ctx -> {
    84	            LocalDate night = readDate(ctx);
    85	            ctx.contentType("text/csv; charset=utf-8").result(occupancyReport.generate(night));
    86	        });
    87	        server.get("/reports/revenue", ctx -> {
    88	            YearMonth month = readMonth(ctx);
    89	            ctx.contentType("text/csv; charset=utf-8").result(revenueReport.generate(month));
    90	        });
    91	    }
    92	
    93	    private void registerErrorHandling() {
    94	        server.exception(HotelException.class, (exception, ctx) -> {
    95	            ctx.status(httpStatus(exception.errorCode()));
    96	            ctx.json(new ErrorResponse(exception.errorCode().name(), exception.getMessage()));
    97	        });
    98	    }
    99	
   100	    private static int httpStatus(ErrorCode errorCode) {
   101	        return switch (errorCode) {
   102	            case INVALID_REQUEST -> 400;
   103	            case ROOM_NOT_FOUND, RESERVATION_NOT_FOUND -> 404;
   104	            case ROOM_UNAVAILABLE, OPERATION_NOT_ALLOWED -> 409;
   105	            case CAPACITY_EXCEEDED -> 422;
   106	        };
   107	    }
   108	
   109	    private static NewReservation readNewReservation(Context ctx) {
   110	        CreateReservationRequest body;
   111	        try {
   112	            body = ctx.bodyAsClass(CreateReservationRequest.class);
   113	        } catch (Exception unreadableBody) { // Jackson's own exceptions are checked, but reach here unwrapped
   114	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the body is not a valid reservation request");
   115	        }
   116	        if (body == null
   117	                || body.roomNumber() == null
   118	                || isBlank(body.guestName())
   119	                || isBlank(body.guestEmail())
   120	                || body.checkIn() == null
   121	                || body.checkOut() == null
   122	                || body.guests() == null
   123	                || body.ratePlan() == null) {
   124	            throw new HotelException(ErrorCode.INVALID_REQUEST, "every field of the reservation is required");
   125	        }
   126	        Guest guest = new Guest(
   127	                body.guestName(),
   128	                body.guestEmail(),
   129	                blankToNull(body.guestCpf()),
   130	                blankToNull(body.companyCnpj()),
   131	                blankToNull(body.companyName()),
   132	                blankToNull(body.guestPassport()),
   133	                blankToNull(body.guestCountry()));
   134	        requireOneIdentification(guest);
   135	        return new NewReservation(
   136	                body.roomNumber(), guest, body.checkIn(), body.checkOut(), body.guests(), body.ratePlan());
   137	    }
   138	
   139	    /** The guest needs a CPF, or a CNPJ with the company name, or a passport with the country: only one of them. */
   140	    private static void requireOneIdentification(Guest guest) {
   141	        boolean cpf = guest.cpf() != null;
   142	        boolean anyCompany = guest.companyCnpj() != null || guest.companyName() != null;
   143	        boolean company = guest.companyCnpj() != null && guest.companyName() != null;
   144	        boolean anyForeigner = guest.passport() != null || guest.country() != null;
   145	        boolean foreigner = guest.passport() != null && guest.country() != null;
   146	        boolean valid = (cpf && !anyCompany && !anyForeigner)
   147	                || (company && !cpf && !anyForeigner)
   148	                || (foreigner && !cpf && !anyCompany);
   149	        if (!valid) {
   150	            throw new HotelException(
   151	                    ErrorCode.INVALID_REQUEST,
   152	                    "identify the guest by exactly one of: guestCpf; companyCnpj with companyName; "
   153	                            + "guestPassport with guestCountry");
   154	        }
   155	    }
   156	
   157	    private static String blankToNull(String text) {
   158	        return isBlank(text) ? null : text;
   159	    }
   160	
   161	    private static long reservationId(Context ctx) {
   162	        String id = ctx.pathParam("id");
   163	        try {
   164	            return Long.parseLong(id);
   165	        } catch (NumberFormatException notANumber) {
   166	            throw new HotelException(ErrorCode.RESERVATION_NOT_FOUND, "reservation " + id + " does not exist");
   167	        }
   168	    }
   169	
   170	    private static LocalDate readDate(Context ctx) {
   171	        String date = requiredQueryParam(ctx, "date");
   172	        try {
   173	            return LocalDate.parse(date);
   174	        } catch (DateTimeParseException badDate) {
   175	            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + date + "' is not a date (yyyy-MM-dd)");
   176	        }
   177	    }
   178	
   179	    private static YearMonth readMonth(Context ctx) {
   180	        String month = requiredQueryParam(ctx, "month");
   181	        try {
   182	            return YearMonth.parse(month);
   183	        } catch (DateTimeParseException badMonth) {
   184	            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + month + "' is not a month (yyyy-MM)");
   185	        }
   186	    }
   187	
   188	    private static String requiredQueryParam(Context ctx, String name) {
   189	        String value = ctx.queryParam(name);
   190	        if (value == null) {
   191	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the query parameter '" + name + "' is required");
   192	        }
   193	        return value;
   194	    }
   195	
   196	    private static boolean isBlank(String text) {
   197	        return text == null || text.isBlank();
   198	    }
   199	}

